import importlib.util, os
spec = importlib.util.spec_from_file_location("lib", os.path.join(os.path.dirname(__file__), "es-stories-lib.py"))
lib = importlib.util.module_from_spec(spec); spec.loader.exec_module(lib)
story = lib.story

S = []
S.append(story("el_juicio_de_la_bruja", "A2-1", "El juicio de la bruja",
 ("Cả lớp của cô Ortega dựng một phiên tòa: bị cáo là mụ phù thủy trong truyện «Hansel và Gretel».", "Ms Ortega's class stages a trial: the accused is the witch from 'Hansel and Gretel'."),
 ["bruja", "pastel", "juicio", "testigo"],
 [("N", "En la clase de la profesora Ortega, los niños estudian la ley.", "Trong lớp của cô Ortega, các em đang học về pháp luật.", "In Ms Ortega's class, the children are studying the law."),
  ("N", "Hoy van a actuar en un juicio, pero en un juicio diferente: el de la bruja de «Hansel y Gretel».", "Hôm nay các em sẽ diễn một phiên tòa, nhưng là một phiên tòa đặc biệt: xử mụ phù thủy trong truyện «Hansel và Gretel».", "Today they are going to act out a trial, but an unusual one: the trial of the witch from 'Hansel and Gretel'."),
  ("N", "Todos saben la historia: dos hermanos se pierden lejos de casa y encuentran una casa cubierta de pastel.", "Ai cũng biết câu chuyện: hai anh em bị lạc xa nhà và tìm thấy một ngôi nhà phủ đầy bánh ngọt.", "Everyone knows the story: a brother and sister get lost far from home and find a house covered in cake."),
  ("N", "Allí vive una señora que atrapa a los niños y quiere comérselos.", "Ở đó có một bà già chuyên bắt trẻ con để ăn thịt.", "A woman lives there who catches the children and wants to eat them."),
  ("N", "La profesora es la jueza. Inés es la bruja, y Álex es su abogado.", "Cô giáo làm thẩm phán. Inés đóng vai mụ phù thủy, còn Álex là luật sư của mụ.", "The teacher is the judge. Inés is the witch, and Álex is her lawyer."),
  ("N", "Lucas y Sofía son Hansel y Gretel, los testigos.", "Lucas và Sofía đóng vai Hansel và Gretel, hai nhân chứng.", "Lucas and Sofía are Hansel and Gretel, the witnesses."),
  ("A", "¡Orden, por favor! Comienza el juicio.", "Trật tự nào! Phiên tòa bắt đầu.", "Order, please! The trial begins."),
  ("A", "Señora, usted atrapó a dos muchachos y quiso comérselos. ¿Es así?", "Thưa bà, bà đã bắt hai đứa trẻ và định ăn thịt chúng. Có đúng vậy không?", "Madam, you caught two youngsters and tried to eat them. Is that so?"),
  ("N", "Inés pone cara de mala, y la clase se ríe.", "Inés làm mặt độc ác, và cả lớp cười ồ.", "Inés pulls a wicked face, and the class laughs."),
  ("N", "Lucas, el primer testigo, explica que la señora lo tuvo una semana en una habitación oscura.", "Lucas, nhân chứng thứ nhất, kể rằng bà ta đã nhốt cậu một tuần trong một căn phòng tối.", "Lucas, the first witness, explains that the woman kept him in a dark room for a week."),
  ("B", "Señora jueza, no es justo culpar a mi cliente de todo.", "Thưa quý tòa, đổ hết lỗi cho thân chủ của tôi là không công bằng.", "Your Honour, it isn't fair to blame my client for everything."),
  ("B", "Los niños entraron sin preguntar y se comieron una parte de su casa. ¡Era su hogar!", "Bọn trẻ tự ý vào nhà và ăn mất một phần ngôi nhà của bà ấy. Đó là tổ ấm của bà ấy!", "The children went in without asking and ate part of her house. It was her home!"),
  ("B", "En el pasado, mi cliente era una señora pobre y sola. Nadie la quería.", "Trước đây, thân chủ của tôi là một bà lão nghèo và cô đơn. Chẳng ai thương bà ấy.", "In the past my client was a poor, lonely woman. Nobody loved her."),
  ("N", "Todos miran a Inés. Ella pone cara triste.", "Mọi người nhìn Inés. Cô bé làm mặt buồn.", "Everyone looks at Inés. She pulls a sad face."),
  ("A", "¿Y los niños? ¿Ellos no tienen la culpa de nada?", "Thế còn bọn trẻ? Chúng không có lỗi gì sao?", "And the children? Are they not to blame for anything?"),
  ("N", "Sofía, la segunda testigo, se levanta.", "Sofía, nhân chứng thứ hai, đứng dậy.", "Sofía, the second witness, stands up."),
  ("N", "Explica que ella y su hermano tenían mucha hambre, y que después ella liberó a Hansel y escaparon juntos.", "Cô bé kể rằng hai anh em lúc đó rất đói, và sau đó cô đã giải thoát cho Hansel rồi cả hai cùng trốn thoát.", "She explains that she and her brother were very hungry, and that later she freed Hansel and they escaped together."),
  ("B", "¿Lo ven? Fue un problema de hambre, no un crimen.", "Mọi người thấy chưa? Đó là chuyện đói khát, chứ đâu phải tội ác.", "You see? It was a matter of hunger, not a crime."),
  ("A", "Bien. Ahora decide la clase. ¿Quién cree que la bruja tiene la culpa?", "Được rồi. Giờ cả lớp quyết định. Ai cho rằng mụ phù thủy có tội?", "Good. Now the class decides. Who thinks the witch is to blame?"),
  ("N", "Veinte manos se levantan. Solo Álex no levanta la mano.", "Hai mươi cánh tay giơ lên. Chỉ có Álex là không giơ tay.", "Twenty hands go up. Only Álex keeps his hand down."),
  ("A", "La bruja tiene la culpa. Su pena: ordenar la clase durante un mes.", "Mụ phù thủy có tội. Hình phạt: dọn dẹp lớp học trong một tháng.", "The witch is guilty. Her sentence: tidying the classroom for a month."),
  ("N", "«¡Eres un abogado estúpido!», le dice Inés a Álex, en broma.", "«Cậu đúng là luật sư ngốc!», Inés nói đùa với Álex.", "\"You're a stupid lawyer!\" Inés tells Álex, as a joke."),
  ("A", "Y tú, Álex, en el futuro tienes que hablar menos de casas y más de la ley.", "Còn em, Álex, lần sau em phải nói ít về nhà cửa và nói nhiều hơn về luật nhé.", "And you, Álex, in future you need to talk less about houses and more about the law.")],
 [("locate", "Ai đóng vai thẩm phán?", "Who plays the judge?", [("Cô giáo Ortega", "Ms Ortega, the teacher"), ("Álex", "Álex"), ("Sofía", "Sofía")], 0),
  ("locate", "Hình phạt dành cho mụ phù thủy là gì?", "What is the witch's sentence?", [("Vào tù", "Prison"), ("Dọn dẹp lớp học trong một tháng", "Tidying the classroom for a month"), ("Xây lại ngôi nhà", "Rebuilding the house")], 1),
  ("infer", "Vì sao Inés gọi Álex là «luật sư ngốc»?", "Why does Inés call Álex a 'stupid lawyer'?", [("Vì cậu ấy cũng giơ tay", "Because he raised his hand too"), ("Vì cậu ấy không giúp được «thân chủ» của mình thắng", "Because he didn't manage to win the case for his 'client'"), ("Vì cậu ấy ăn bánh", "Because he ate the cake")], 1)],
 names=["Ortega", "Hansel", "Gretel", "Inés", "Álex", "Lucas", "Sofía"],
 token_map={"jueza": "es:w:juez", "comérselos": "es:w:comer"}))

S.append(story("la_mudanza", "A1-2", "La mudanza",
 ("Gia đình Clara chuyển đến căn hộ mới gần biển. Một ngày dài với những thùng đồ, và một trận tranh phòng.", "Clara's family moves to a new flat near the sea. A long day of boxes, and a fight over a room."),
 ["piso", "meter", "cargar", "pegar", "colgar"],
 [("N", "La familia de Clara cambia de casa.", "Gia đình Clara chuyển nhà.", "Clara's family is moving house."),
  ("N", "El piso nuevo está en otra parte de la ciudad, cerca del mar.", "Căn hộ mới ở một khu khác của thành phố, gần biển.", "The new flat is in another part of the city, near the sea."),
  ("N", "Es sábado y todos trabajan desde las siete de la mañana.", "Hôm nay thứ Bảy và cả nhà làm việc từ bảy giờ sáng.", "It's Saturday and everyone has been working since seven in the morning."),
  ("N", "Clara y su hermano Diego meten la ropa y los libros en cajas.", "Clara và em trai Diego cho quần áo và sách vào thùng.", "Clara and her brother Diego put the clothes and books into boxes."),
  ("N", "En cada caja, Clara pega un papel con el nombre de una habitación.", "Trên mỗi thùng, Clara dán một tờ giấy ghi tên phòng.", "On each box, Clara sticks a piece of paper with the name of a room."),
  ("B", "Clara, esta caja es demasiado grande. No puedo con ella.", "Chị Clara ơi, thùng này to quá. Em không bê nổi.", "Clara, this box is too big. I can't manage it."),
  ("A", "Espera, que te ayudo.", "Đợi đã, để chị giúp.", "Wait, I'll help you."),
  ("N", "Su padre carga las cajas en un camión pequeño.", "Bố chất các thùng lên một chiếc xe tải nhỏ.", "Their father loads the boxes onto a small lorry."),
  ("N", "Tarda tres horas en cargarlo todo. Después se sienta con la mano en la espalda.", "Bố mất ba tiếng mới chất xong. Rồi bố ngồi xuống, tay đỡ lưng.", "It takes him three hours to load everything. Then he sits down with his hand on his back."),
  ("N", "Su madre saca el resto de las cosas: un par de mesas pequeñas y la cama del perro.", "Mẹ mang nốt chỗ đồ còn lại ra: hai cái bàn nhỏ và cái giường của con chó.", "Their mother brings out the rest of the things: a couple of small tables and the dog's bed."),
  ("N", "Diego mira su habitación, ya sin nada.", "Diego nhìn căn phòng trống trơn của mình.", "Diego looks at his empty room."),
  ("B", "Es raro. Aquí ya no queda nada nuestro.", "Lạ thật. Ở đây chẳng còn gì của mình nữa.", "It's strange. There's nothing of ours left here."),
  ("A", "Ya, pero el piso nuevo va a ser nuestro hogar.", "Ừ, nhưng căn hộ mới sẽ là tổ ấm của mình.", "I know, but the new flat is going to be our home."),
  ("N", "El piso nuevo tiene cuatro habitaciones y una ventana grande al mar. Hoy luce el sol.", "Căn hộ mới có bốn phòng và một cửa sổ lớn nhìn ra biển. Hôm nay trời nắng đẹp.", "The new flat has four rooms and a big window looking out to sea. Today the sun is shining."),
  ("N", "Clara ocupa la habitación de la ventana grande.", "Clara chiếm ngay căn phòng có cửa sổ lớn.", "Clara takes the room with the big window."),
  ("B", "¡No es justo! ¡Yo también quiero esa habitación!", "Không công bằng! Em cũng muốn phòng đó!", "It's not fair! I want that room too!"),
  ("A", "Lo siento. Yo llegué primero.", "Tiếc quá. Chị đến trước mà.", "Sorry. I got here first."),
  ("N", "Su madre los calma: «Un mes cada uno», dice.", "Mẹ dỗ cho hai đứa bình tĩnh: «Mỗi đứa một tháng», mẹ nói.", "Their mother calms them down: \"A month each,\" she says."),
  ("N", "Por la noche, su padre cuelga una foto de la familia al lado de la puerta.", "Buổi tối, bố treo một tấm ảnh gia đình bên cạnh cửa ra vào.", "In the evening, their father hangs a family photo next to the door."),
  ("N", "En la foto están todos delante de su casa amarilla, la casa de antes.", "Trong ảnh, cả nhà đứng trước ngôi nhà màu vàng, ngôi nhà cũ của họ.", "In the photo they are all in front of their yellow house, the old one."),
  ("N", "Mañana tienen que devolver el camión.", "Ngày mai họ phải trả lại chiếc xe tải.", "Tomorrow they have to return the lorry."),
  ("N", "El padre asegura que nunca más va a cambiar de casa.", "Bố khẳng định sẽ không bao giờ chuyển nhà nữa.", "Their father swears he is never moving house again."),
  ("A", "¿Seguro, papá?", "Chắc không bố?", "Are you sure, Dad?"),
  ("N", "Y todos se ríen.", "Và cả nhà cùng cười.", "And they all laugh.")],
 [("locate", "Clara dán gì lên mỗi thùng?", "What does Clara stick on each box?", [("Một tấm ảnh", "A photo"), ("Một tờ giấy ghi tên phòng", "A paper with the name of a room"), ("Tên của Diego", "Diego's name")], 1),
  ("locate", "Mẹ giải quyết chuyện tranh phòng thế nào?", "How does their mother settle the fight over the room?", [("Mỗi đứa ở một tháng", "Each child gets it for a month"), ("Cho Diego căn phòng đó", "She gives the room to Diego"), ("Mẹ tự lấy căn phòng đó", "She takes the room herself")], 0),
  ("infer", "Vì sao cả nhà cười khi bố nói sẽ không bao giờ chuyển nhà nữa?", "Why does everyone laugh when Dad says he will never move again?", [("Vì bố rất thích chuyển nhà", "Because Dad loves moving"), ("Vì không ai chắc bố giữ được lời hứa đó", "Because nobody is sure he will keep that promise"), ("Vì xe tải bị hỏng", "Because the lorry broke down")], 1)],
 names=["Clara", "Diego"],
 token_map={"cargarlo": "es:w:cargar", "siento": "es:w:sentir", "espera": "es:w:esperar"}))

S.append(story("dos_dias_en_granada", "A2-1", "Dos días en Granada",
 ("Hugo đưa bạn gái Sofía đi Granada. Anh mang theo một chiếc hộp nhỏ đựng nhẫn… cho đến khi nó biến mất.", "Hugo takes his girlfriend Sofía to Granada. He brings a little box with a ring in it… until it disappears."),
 ["anillo", "casar", "mostrar", "desaparecer", "relacion"],
 [("N", "Hugo y Sofía llevaban cinco años juntos.", "Hugo và Sofía đã yêu nhau được năm năm.", "Hugo and Sofía had been together for five years."),
  ("N", "Para el cumpleaños de Sofía, Hugo preparó un viaje de dos días a Granada.", "Nhân sinh nhật Sofía, Hugo chuẩn bị một chuyến đi Granada hai ngày.", "For Sofía's birthday, Hugo planned a two-day trip to Granada."),
  ("N", "Pero Hugo no le contó una cosa: llevaba un anillo para ella en una caja pequeña.", "Nhưng có một chuyện Hugo không kể với cô: anh mang theo một chiếc nhẫn cho cô, đựng trong một chiếc hộp nhỏ.", "But Hugo didn't tell her one thing: he was carrying a ring for her in a little box."),
  ("N", "Quería hacerle una pregunta muy importante delante de la Alhambra, cuando se pusiera el sol.", "Anh muốn hỏi cô một câu rất quan trọng trước cung điện Alhambra, vào lúc mặt trời lặn.", "He wanted to ask her a very important question in front of the Alhambra, at sunset."),
  ("N", "El primer día caminaron por las calles del centro y comieron en un bar pequeño.", "Ngày đầu tiên, hai người dạo bộ qua các con phố trung tâm và ăn trưa ở một quán bar nhỏ.", "On the first day they walked through the streets of the centre and ate in a small bar."),
  ("A", "¿Qué te pasa? Estás muy raro hoy.", "Anh sao thế? Hôm nay trông anh lạ lắm.", "What's the matter with you? You're acting very strange today."),
  ("B", "¿Yo? Nada, nada. Es que tengo hambre.", "Anh á? Không có gì đâu. Tại anh đói thôi.", "Me? Nothing, nothing. I'm just hungry."),
  ("N", "Por la tarde subieron a una plaza desde donde se ve toda la Alhambra.", "Buổi chiều, họ lên một quảng trường từ đó nhìn thấy toàn cảnh Alhambra.", "In the afternoon they went up to a square with a view of the whole Alhambra."),
  ("N", "En la plaza sonaba música, y la luz sobre la ciudad era maravillosa. Era el momento.", "Trên quảng trường có tiếng nhạc vang lên, và ánh sáng phủ lên thành phố đẹp tuyệt vời. Đã đến lúc rồi.", "Music was playing in the square, and the light over the city was wonderful. This was the moment."),
  ("N", "Hugo buscó la caja pequeña en su ropa. ¡No estaba!", "Hugo lục tìm chiếc hộp nhỏ trong túi quần áo. Không thấy đâu cả!", "Hugo felt in his clothes for the little box. It wasn't there!"),
  ("N", "La buscó en todas partes, pero nada: la caja desapareció.", "Anh tìm khắp nơi, nhưng vô ích: chiếc hộp đã biến mất.", "He looked for it everywhere, but nothing: the box had vanished."),
  ("A", "Hugo, ¿qué buscas? Estás muy preocupado.", "Hugo, anh tìm gì thế? Trông anh lo lắng quá.", "Hugo, what are you looking for? You look very worried."),
  ("B", "No, no… Bueno, sí. Mi… mi móvil.", "Không, không… À, có. Cái… cái điện thoại của anh.", "No, no… Well, yes. My… my phone."),
  ("A", "¿Tu móvil? Lo tienes en la mano.", "Điện thoại á? Nó đang ở trên tay anh kìa.", "Your phone? It's in your hand."),
  ("N", "Hugo no sabía qué decir. Sofía se rio y le mostró la caja pequeña.", "Hugo không biết nói gì. Sofía bật cười và đưa cho anh xem chiếc hộp nhỏ.", "Hugo didn't know what to say. Sofía laughed and showed him the little box."),
  ("A", "Esta mañana la encontré en la cama del hotel.", "Sáng nay em thấy nó trên giường ở khách sạn.", "This morning I found it on the bed at the hotel."),
  ("B", "Entonces, ¿ya lo sabías?", "Vậy là… em biết từ trước rồi à?", "So… you already knew?"),
  ("A", "Sí. Y llevo todo el día esperando la pregunta.", "Ừ. Và em đã chờ câu hỏi đó cả ngày.", "Yes. And I've been waiting for the question all day."),
  ("N", "Hugo se rio, abrió la caja y, ahora sí, hizo la pregunta.", "Hugo bật cười, mở hộp ra và lần này thì anh hỏi thật.", "Hugo laughed, opened the box and, this time, asked the question."),
  ("B", "Sofía, ¿quieres casarte conmigo?", "Sofía, em có muốn lấy anh không?", "Sofía, will you marry me?"),
  ("A", "¡Claro que sí!", "Tất nhiên là có!", "Of course I will!"),
  ("N", "Se besaron, y toda la gente de la plaza los miró.", "Hai người hôn nhau, và cả quảng trường nhìn về phía họ.", "They kissed, and everyone in the square looked at them."),
  ("N", "Así empezó una nueva parte de su relación: con un anillo perdido y encontrado.", "Thế là một chặng mới trong mối quan hệ của họ bắt đầu: với một chiếc nhẫn bị mất rồi lại tìm thấy.", "And so a new part of their relationship began: with a ring lost and found.")],
 [("locate", "Hugo muốn hỏi Sofía câu quan trọng ở đâu?", "Where does Hugo want to ask Sofía the important question?", [("Trong một quán bar nhỏ", "In a small bar"), ("Ở khách sạn", "At the hotel"), ("Trước cung điện Alhambra", "In front of the Alhambra")], 2),
  ("locate", "Sofía đã tìm thấy chiếc hộp nhỏ ở đâu?", "Where had Sofía found the little box?", [("Trên giường ở khách sạn", "On the bed at the hotel"), ("Trong điện thoại của Hugo", "In Hugo's phone"), ("Ở quán bar", "At the bar")], 0),
  ("infer", "Vì sao ngay từ ngày đầu Sofía đã thấy Hugo «lạ lắm»?", "Why does Sofía find Hugo 'very strange' on the first day?", [("Vì Hugo bị ốm", "Because Hugo is ill"), ("Vì Hugo hồi hộp với câu hỏi anh định hỏi", "Because Hugo is nervous about the question he plans to ask"), ("Vì Hugo làm mất điện thoại", "Because Hugo lost his phone")], 1)],
 names=["Hugo", "Sofía", "Granada", "Alhambra"],
 token_map={"casarte": "es:w:casar", "hacerle": "es:w:hacer"}))
lib.write_batch("04", S)
